users.forEach(u => console.log(JSON.stringify(u, null, 2)));

// Find product
console.log('\n=== PRODUCT PROD-FA0948 ===');
const prod = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-FA0948'\").all();
prod.forEach(p => console.log(JSON.stringify(p, null, 2)));

// Find orders for Sofia's user_id(s) that include PROD-FA0948
const userIds = users.map(u => u.user_id);
console.log('\nUser IDs for Sofia:', userIds);

// Find order items with PROD-FA0948
