const items = db.prepare(\"SELECT * FROM order_items WHERE product_id = 'PROD-FA0948'\").all();
items.forEach(i => console.log(JSON.stringify(i)));

// Find orders for those items
const orderIds = [...new Set(items.map(i => i.order_id))];
console.log('\n=== ORDERS CONTAINING PROD-FA0948 ===');
for (const oid of orderIds) {
  const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(oid);
  console.log(JSON.stringify(order));
}
