const fs = require('fs');
const lines = fs.readFileSync('/workspace/data/support_tickets.csv','utf8').trim().split('\n').slice(1);
const agents = {};
lines.forEach(l => {
  const cols = l.split(',');
  const status = cols[4], agent = cols[5];
  if (!agents[agent]) agents[agent] = {resolved:0, active:0, tickets:[]};
  if (status === 'resolved') agents[agent].resolved++;
  else { agents[agent].active++; agents[agent].tickets.push(cols[0] + '(' + status + ')'); }
});
console.log('Agent workloads (active/unresolved tickets):');
Object.entries(agents).forEach(([a,v]) => console.log('  ' + a + ': ' + v.active + ' active, ' + v.resolved + ' resolved', v.tickets.length ? '-> ' + v.tickets.join(', ') : ''));
"

